   113→    }
   114→    return { success: false, error: `Account not found: ${idOrName}` };
   115→  }
   116→
   117→  const exchange = getExchange(record.exchange);
   118→  const masked: Partial<Record<CredentialField, string>> = {};
   119→  for (const field of exchange.fields) {
   120→    const value = record[field as keyof AccountRecord] as string | undefined;
   121→    if (value) masked[field] = maskCredential(value);
   122→  }
