   136→  if (byName.length > 1) {
   137→    return { success: false, error: `Multiple accounts match name "${idOrName}". Use account ID instead.` };
   138→  }
   139→  const idx = accounts.findIndex((a) => a.id === idOrName || a.name === idOrName);
   140→  if (idx === -1) return { success: false, error: `Account not found: ${idOrName}` };
   141→
   142→  const record = accounts[idx];
   143→
   144→  if (input.name) {
   145→    const nameErr = validateName(input.name);
   146→    if (nameErr) return { success: false, error: nameErr };
   147→    record.name = input.name.trim();
